// Package main — the generated files' digests: every file kit generates from
// the design names its design file and two sha256 digests in its header, and
// both must hold — the design file's bytes, and the file's own body.
package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"os"
	"path"
	"path/filepath"
	"regexp"
	"slices"
	"strings"
)

const (
	// kitHeaderPrefix opens the header of every file kit generates.
	kitHeaderPrefix string = "// Code generated by kit from "
	// designGenGlob matches a generated port file's name.
	designGenGlob string = "design_gen*.go"
)

// kitHeader is the first line of a file kit generates: the design file,
// relative to the repository's root, the sha256 of its bytes, and the sha256
// of the generated file's body — every byte after this line's newline:
//
//	// Code generated by kit from design/app/lock.yaml (sha256 <hex>, body <hex>). DO NOT EDIT.
//
// It is a generated-file comment as the go command defines one, so every
// linter that skips generated code skips these files.
var kitHeader = regexp.MustCompile(`^// Code generated by kit from (\S+) \(sha256 ([0-9a-f]{64}), body ([0-9a-f]{64})\)\. DO NOT EDIT\.$`)

// digestFindings checks every generated file of the project's package
// directories: a pin or port file without a kit header, a design file the
// header names that is missing or outside the repository, a design file whose
// bytes changed since kit generated from it, and a body edited by hand.
func digestFindings(root string, dirs []packageDir) []string {
	var out []string
	//: each package directory, its generated files by name.
	for _, d := range dirs {
		//: each file kit generates, or claims to.
		for _, name := range generatedFiles(d.dir) {
			where := relSlash(root, filepath.Join(d.dir, name))
			//: every problem of the file.
			for _, problem := range checkGenerated(root, filepath.Join(d.dir, name)) {
				out = append(out, where+": "+problem)
			}
		}
	}
	//: every finding.
	return out
}

// generatedFiles names the files of a directory kit generates: a pin file, a
// port file, or any Go file whose first line is a kit header.
func generatedFiles(dir string) []string {
	entries, err := os.ReadDir(dir)
	//: a directory that cannot be read holds nothing this can judge; the
	//: loader read it a moment ago, so this is not expected.
	if err != nil {
		//: nothing.
		return nil
	}
	var out []string
	//: every Go file of the directory.
	for _, e := range entries {
		//: a directory or a file of another language.
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") {
			continue
		}
		//: claimed by its name, or by its header.
		if byName(e.Name()) || hasKitHeader(filepath.Join(dir, e.Name())) {
			out = append(out, e.Name())
		}
	}
	slices.Sort(out)
	//: the generated files.
	return out
}

// byName reports whether a file's name says kit generates it: a pin file or
// a port file. Both patterns are constants path.Match accepts, so an error
// would only mean no match.
func byName(name string) bool {
	//: each pattern of a generated file's name.
	for _, pattern := range []string{pinGlob, designGenGlob} {
		//: a name the pattern matches.
		if ok, err := path.Match(pattern, name); err == nil && ok {
			//: generated.
			return true
		}
	}
	//: a hand-written file.
	return false
}

// hasKitHeader reports whether a file's first line opens a kit header.
func hasKitHeader(path string) bool {
	first, _, err := readFirstLine(path)
	//: the header's opening words.
	return err == nil && strings.HasPrefix(first, kitHeaderPrefix)
}

// checkGenerated returns the problems of one generated file.
func checkGenerated(root, file string) []string {
	first, raw, err := readFirstLine(file)
	//: a file that cannot be read.
	if err != nil {
		//: one problem.
		return []string{"unreadable: " + err.Error()}
	}
	m := kitHeader.FindStringSubmatch(first)
	//: a generated file must say what it was generated from.
	if m == nil {
		//: one problem: no header, or one in another shape.
		return []string{"no kit header: its first line must be `" + kitHeaderPrefix + "<design file> (sha256 <hex>, body <hex>). DO NOT EDIT.`"}
	}
	var out []string
	//: the design file's bytes, as kit read them.
	if problem := checkDesignDigest(root, m[1], m[2]); problem != "" {
		out = append(out, problem)
	}
	body := raw[len(first)+min(1, len(raw)-len(first)):]
	//: the body, as kit wrote it.
	if got := sha256Hex(body); got != m[3] {
		out = append(out, fmt.Sprintf("body edited: its body hashes to %s, the header says %s — a generated file is changed by changing the design and running kit gen, never by hand", got, m[3]))
	}
	//: the file's problems.
	return out
}

// checkDesignDigest checks the design file a header names: inside the
// repository, present, and hashing to the header's digest. It returns the
// problem, or "".
func checkDesignDigest(root, design, want string) string {
	clean := path.Clean(design)
	//: a design file is named relative to the repository's root, inside it.
	if path.IsAbs(clean) || clean == ".." || strings.HasPrefix(clean, "../") {
		//: refuse to read outside.
		return "names a design file outside the repository: " + design
	}
	raw, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(clean)))
	//: a design file that is gone.
	if os.IsNotExist(err) {
		//: the generated file has no design any more.
		return "design file missing: " + design + " does not exist"
	}
	//: any other failure to read it.
	if err != nil {
		//: as the read failed.
		return "design file unreadable: " + err.Error()
	}
	//: the design changed since kit generated from it.
	if got := sha256Hex(raw); got != want {
		//: a design edit without kit gen.
		return fmt.Sprintf("design file changed: %s hashes to %s, the header says %s — run kit gen", design, got, want)
	}
	//: the design is the one generated from.
	return ""
}

// sha256Hex is the sha256 of b, in lower-case hex.
func sha256Hex(b []byte) string {
	sum := sha256.Sum256(b)
	//: 64 hex digits.
	return hex.EncodeToString(sum[:])
}

// readFirstLine reads a file's first line, without its newline, and the whole
// file.
func readFirstLine(path string) (string, []byte, error) {
	raw, err := os.ReadFile(path)
	//: a file that cannot be read.
	if err != nil {
		//: as the read failed.
		return "", nil, err
	}
	first, _, _ := strings.Cut(string(raw), "\n")
	//: the line and the whole file.
	return first, raw, nil
}
